function renderSettings(){const voiceOK=!!(window.SpeechRecognition||window.webkitSpeechRecognition);const swOK='serviceWorker' in navigator;const storageInfo=(()=>{const err=window.OrbitStore?.state().error;if(err)return 'STORAGE ERROR: '+err;try{return (JSON.stringify(state).length/1024).toFixed(1)+' KB of Orbit records';}catch{return 'Unknown';}})();$('#settings-content').innerHTML=heading('DEVICE / PREFERENCES','Settings','Manage local intelligence, secure boundaries, records and personalisation.')+`<div class="settings-group"><h3>Connection status</h3><div class="setting-row"><div><span class="label-title">Operating mode</span><span class="label-desc">Orbit is operating independently. No Framework Command service or secure pairing exists.</span></div><span class="tag amber">LOCAL · UNPAIRED</span></div><div class="setting-row"><div><span class="label-title">Framework Command</span><span class="label-desc">No pairing or communication endpoint has been installed.</span></div><span class="tag amber">NOT PAIRED</span></div><div class="setting-row"><div><span class="label-title">Last synchronised</span><span class="label-desc">The future app will timestamp cached data and validate pending instructions.</span></div><span class="setting-value">Never</span></div></div><div class="settings-group"><h3>Offline intelligence — Orbit's local brain</h3><div class="setting-row"><div><span class="label-title">Offline model · WebLLM</span><span class="label-desc">A small language model that runs on this device, separate from Framework Command. The first installation downloads approximately 0.5 GB or more of model/runtime files; browser storage and hardware support are required.</span></div><span id="brain-state" class="tag teal">${window.OrbitOfflineAI?.isReady()?'READY':'NOT LOADED'}</span></div><div class="setting-row"><div><span class="label-title">Install or load offline brain</span><span class="label-desc" id="brain-progress">${window.OrbitOfflineAI?.isReady()?'Local inference is ready.':'Download on Wi-Fi; actual cached model availability is verified when you load and test it. Safari may clear browser storage.'}</span></div><button class="button-outline" data-action="install-brain">${window.OrbitOfflineAI?.isReady()?'Verify':'Install model'}</button></div><div class="setting-row"><div><span class="label-title">Hardware capability</span><span class="label-desc">On-device AI requires WebGPU; this may not work on every iPhone or iPad. No cloud AI fallback is used.</span></div><span class="tag ${navigator.gpu?'teal':'amber'}">${navigator.gpu?'WEBGPU DETECTED':'WEBGPU UNAVAILABLE'}</span></div></div><div class="settings-group"><h3>Model choice</h3><div class="setting-row"><div><span class="label-title">Current model</span><span class="label-desc">The larger model may exceed Safari memory limits; install only after testing compatibility.</span></div><div class="option-row">${(window.OrbitOfflineAI?.MODELS||[]).map(m=>`<button data-model-id="${esc(m.id)}" class="${window.OrbitOfflineAI.MODEL_ID===m.id?'selected':''}">${m.id.includes('1.5B')?'1.5B':'0.5B'}</button>`).join('')}</div></div></div><div class="settings-group"><h3>Appearance & voice</h3><div class="setting-row"><div><span class="label-title">Interface accent</span><span class="label-desc">Choose Orbit’s appearance across mobile workspaces.</span></div><div class="option-row"><button class="${state.accent==='teal'?'selected':''}" data-set-accent="teal">Teal</button><button class="${state.accent==='blue'?'selected':''}" data-set-accent="blue">Blue</button><button class="${state.accent==='silver'?'selected':''}" data-set-accent="silver">Silver</button></div></div><div class="setting-row"><div><span class="label-title">Ambient animation</span><span class="label-desc">Orbit hovering, waving and reacting to interactions.</span></div><button class="toggle-switch ${state.motion?'on':''}" data-toggle="motion" role="switch" aria-checked="${state.motion}" aria-label="Ambient animation"></button></div><div class="setting-row"><div><span class="label-title">Read responses aloud</span><span class="label-desc">Uses the browser's speech synthesis if provided by your device.</span></div><button class="toggle-switch ${state.tts?'on':''}" data-toggle="tts" role="switch" aria-checked="${state.tts}" aria-label="Read responses aloud"></button></div><div class="setting-row"><div><span class="label-title">Microphone input</span><span class="label-desc">${voiceOK?'Browser speech recognition is available, but offline processing is not guaranteed.':'Browser speech recognition is not available here.'} Transcription may be handled by an external speech service.</span></div><span class="tag ${voiceOK?'teal':'amber'}">${voiceOK?'BROWSER READY':'NOT AVAILABLE'}</span></div></div><div class="settings-group"><h3>Privacy & local data</h3><div class="setting-row"><div><span class="label-title">Device storage</span><span class="label-desc">IndexedDB records; not end-to-end encrypted. Back up your data and do not store sensitive records here.</span></div><span class="setting-value">${esc(storageInfo)}</span></div><div class="setting-row"><div><span class="label-title">Offline app files</span><span class="label-desc">App assets cached for offline use; model weights have their own browser storage, which Safari can evict.</span></div><span class="tag">${swOK?'SUPPORTED BY BROWSER':'UNAVAILABLE'}</span></div><div class="setting-row"><div><span class="label-title">Security boundary</span><span class="label-desc">Face ID, encryption, signed policies and device revocation are not implemented in the prototype.</span></div><span class="tag amber">NOT CONFIGURED</span></div><div class="setting-row"><div><span class="label-title">Export local data</span><span class="label-desc">Download your local chats, reports and notes as JSON.</span></div><button class="button-outline" data-action="export-data">Backup</button></div><div class="setting-row"><div><span class="label-title">Restore Orbit data</span><span class="label-desc">Import a validated Orbit v3 backup file. This replaces current local records.</span></div><button class="button-outline" data-action="import-data">Restore</button></div><div class="setting-row"><div><span class="label-title">Reset local data</span><span class="label-desc">Erase this browser's local Orbit data and restore its defaults.</span></div><button class="danger-button" data-action="reset-data">Clear data</button></div></div><div class="section-heading"><h3>Build information</h3></div><div class="info-lines"><div class="info-line"><span>Orbit Mobile UI</span><strong>Orbit 3.0</strong></div><div class="info-line"><span>AI inference</span><strong>${window.OrbitOfflineAI?.isReady()?'Local AI active':'Install in Offline intelligence'}</strong></div><div class="info-line"><span>Authoritative policy</span><strong>Not loaded</strong></div><div class="info-line"><span>Framework gateway</span><strong>Not implemented</strong></div><div class="info-line"><span>Live notifications</span><strong>Not implemented</strong></div></div>`;}
function renderChat(){const list=$('#message-list'),has=state.messages.length>0;$('#home-idle').hidden=has;$('#chat-view').hidden=!has;
 const ch=state.conversations.find(c=>c.id===state.activeConversationId);const t=$('#chat-current-title');if(t)t.textContent=ch?.title||'Conversation';
 if(!has)return;
 list.innerHTML=state.messages.map(m=>`<div class="message ${m.role==='user'?'user':'orbit'}"><div class="message-avatar">${m.role==='user'?'YOU':robotIcon}</div><div class="message-main"><div class="message-header">${m.role==='user'?'You':'Orbit'} · ${esc(date(m.at,true))}</div><div class="message-body">${esc(m.text)}</div><div class="message-meta">${m.role==='orbit'?`<span class="message-tag">${m.source==='local'?'ON-DEVICE AI':m.source==='error'?'AI UNAVAILABLE':m.source==='thinking'?'GENERATING':'LOCAL ASSISTANCE'}</span>`:'<span>Saved on this device</span>'}</div>${m.role==='orbit'?`<div class="message-actions"><button data-copy-message="${esc(m.id)}">${ico('copy')} Copy</button><button data-save-message="${esc(m.id)}">${ico('file')} Save as draft</button></div>`:''}</div></div>`).join('');list.scrollTop=list.scrollHeight;}
function localHelp(q){const query=q.toLowerCase();const sources=[...state.notes.map(x=>({title:x.title,body:x.body,type:'Note'})),...state.reports.map(x=>({title:x.title,body:x.body,type:'Report'}))];const hits=sources.filter(x=>(x.title+' '+x.body).toLowerCase().includes(query.split(/\s+/).filter(x=>x.length>3)[0]||query)).slice(0,4);
 if(hits.length)return 'I found '+hits.length+' matching local records: '+hits.map(x=>x.type+' — '+x.title).join('; ')+'. Open Search to inspect them. My language model is not loaded, so I cannot analyse them conversationally yet.';
 return 'My offline language model is not loaded. Open Settings → Offline intelligence to install and verify it on this device. Your local notes, reports, inspections and conversation history remain available without the model. I cannot contact Framework Command.';}
function relevantRecords(query){const tokens=new Set(query.toLowerCase().match(/[a-z]{4,}/g)||[]),docs=[...state.notes.map(x=>({...x,type:'Note'})),...state.reports.map(x=>({...x,type:'Report'}))];return docs.map(d=>({title:d.title,body:d.body,score:[...tokens].reduce((n,w)=>n+((d.title+' '+d.body).toLowerCase().includes(w)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3);}
function animateOrbit(kind='wave',onDone=null){
 const map={wave:'wave',working:'thinking',review:'reviewing',waiting:'waiting',jump:'happy',blocked:'error',idle:'idle'};
 window.OrbitMotion?.play(map[kind]||kind);
 if(onDone)setTimeout(onDone,1200);
}
async function submitMessage(msg){
 const t=String(msg||'').trim();if(!t)return;if(chatBusy){toast('Orbit is completing your previous request.');return;}
 const ai=window.OrbitOfflineAI,previous=[...state.messages];chatBusy=true;
 window.OrbitMotion?.play('thinking');const now=new Date().toISOString();
 state.messages.push({id:uid(),role:'user',text:t,at:now});
 const placeholder={id:uid(),role:'orbit',text:'',at:new Date().toISOString(),source:'thinking'};
 state.messages.push(placeholder);save();renderChat();$('#chat-input').value='';resizeChat();
 const send=$('#chat-form .composer-send');if(send)send.disabled=true;
 let lastRendered=0;
 try{
  if(!ai?.isReady()){
   placeholder.text=localHelp(t);placeholder.source='local-help';
  }else{
   placeholder.text='Orbit is thinking locally…';
   const reply=await ai.reply([...previous,{role:'user',text:t}],null,txt=>{
     placeholder.text=txt;const now=Date.now();if(now-lastRendered>75){renderChat();lastRendered=now;}
   },relevantRecords(t));
   placeholder.text=reply;placeholder.source='local';
  }
 }catch(e){placeholder.text='Orbit could not complete local inference: '+(e?.message||String(e))+'. Check Settings → Offline intelligence. Nothing was sent to cloud AI.';placeholder.source='error';}
 finally{save();renderChat();updateChrome();chatBusy=false;if(send)send.disabled=false;window.OrbitMotion?.play(placeholder.source==='error'?'error':'happy');}
 if(state.tts&&'speechSynthesis' in window&&placeholder.source==='local'){
  try{speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(placeholder.text);utter.rate=1.02;utter.onstart=()=>window.OrbitMotion?.play('speaking');utter.onend=()=>window.OrbitMotion?.play('idle');utter.onerror=()=>window.OrbitMotion?.play('idle');speechSynthesis.speak(utter);}catch{}
 }
}
function resizeChat(){const el=$('#chat-input');el.style.height='27px';el.style.height=Math.min(el.scrollHeight,118)+'px';}
function beginVoice(){window.OrbitMotion?.play('waiting');if(voiceWaiting){try{speechRecogniser?.stop();}catch{}return;}const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec){toast('Voice recognition is not supported by this browser. Use text input.');return;}openModal(sheetHead('VOICE INPUT','Speech recognition')+`<div class="callout">${ico('alert')}<div><strong>Browser-provided speech input</strong><p>Speech recognition may require internet and may use a third-party service. Microphone recognition is browser-provided and not guaranteed to operate offline. Do not dictate confidential information.</p></div></div><p>Choose Start to use your browser's microphone after granting permission. Transcribed speech will be placed into the chat input for review before sending.</p><div class="sheet-footer"><button class="sheet-secondary" data-action="close-modal">Cancel</button><button class="sheet-primary" data-action="start-voice">Start listening</button></div>`);}
function startVoice(){closeModal();const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec)return;try{speechRecogniser=new Rec();speechRecogniser.lang=(navigator.language||'en-AU');speechRecogniser.interimResults=false;speechRecogniser.continuous=false;voiceWaiting=true;window.OrbitMotion?.play('listening');$('#mic-button').classList.add('is-recording');$('#orbit-art').classList.add('listening');speechRecogniser.onresult=e=>{const text=Array.from(e.results).map(r=>r[0]?.transcript||'').join(' ');$('#chat-input').value=($('#chat-input').value+' '+text).trim();resizeChat();toast('Transcript added. Review and press Send.');};speechRecogniser.onerror=e=>{window.OrbitMotion?.play('error');toast(`Voice input unavailable: ${e.error||'browser error'}.`);};speechRecogniser.onend=()=>{voiceWaiting=false;window.OrbitMotion?.play('idle');$('#mic-button').classList.remove('is-recording');$('#orbit-art').classList.remove('listening');};speechRecogniser.start();toast('Listening — browser permission may be required.');}catch{voiceWaiting=false;toast('Could not start browser speech recognition.');}}
