function renderGlobalResults(){const inp=$('#global-query'),out=$('#global-results');if(!inp||!out)return;const q=inp.value.trim().toLowerCase();const src=[...GLOSSARY.map(g=>({type:'Lexicon',label:g.word,summary:g.definition,route:'knowledge',tab:'lexicon'})),...state.notes.map(n=>({type:'Note',label:n.title,summary:n.body,route:'knowledge',tab:'notes',id:n.id})),...state.reports.map(r=>({type:'Report',label:r.title,summary:r.body,route:'reports',id:r.id})),...state.conversations.flatMap(c=>(c.messages||[]).map(m=>({type:m.role==='user'?'Your message':'Orbit reply',label:m.text.slice(0,65),summary:m.text,route:'home',chatId:c.id})))];const matches=(q?src.filter(x=>(x.label+' '+x.summary).toLowerCase().includes(q)):src.slice(0,6)).slice(0,30);out.innerHTML=matches.length?matches.map(m=>`<button class="search-item" data-search-route="${esc(m.route)}" data-search-id="${esc(m.id||'')}" data-search-tab="${esc(m.tab||'')}" data-search-chat="${esc(m.chatId||'')}">${ico(m.type==='Report'?'file':m.type==='Lexicon'?'book':'search')}<div><strong>${esc(m.label)}</strong><span>${esc(m.type)} · ${esc(m.summary.slice(0,88))}</span></div></button>`).join(''):`<div class="empty-state">${ico('search')}<h3>No results</h3><p>Try a different term.</p></div>`;}
